questionvariables.text:
/* Randomise shapes */

redShape:rand(["square", "rectangle"]);
greenShape:rand(["rhombus", "parallelogram"]);
blueShape:rand(["equilateral", "isosceles", "right-angled"]);
purpShape:rand(["kite", "trapezium"]);

triAngle: if blueShape="equilateral" then 60 else if blueShape="isosceles" then rand_with_step(20,50,10) else rand_with_step(50,80,5);

/* Multiple choice options */

ansList1: random_permutation([["rhombus",is(greenShape="rhombus")], ["parallelogram", is(greenShape="parallelogram")], [rand(["square", "rectangle"]), false], [rand(["kite", "trapezium"]), false]]);

ansList2: [["perpendicular",is(greenShape="rhombus")], ["not perpendicular",is(greenShape="parallelogram")]];

ansList3: random_permutation([["kite",is(purpShape="kite")], ["trapezium", is(purpShape="trapezium")], [rand(["square", "rectangle"]), false], [rand(["rhombus", "parallelogram"]), false]]);

ansList4: [["perpendicular",is(purpShape="kite")], ["not perpendicular",is(purpShape="trapezium")]];

tans2: if greenShape="rhombus" then "perpendicular" else "not perpendicular";
tans4: if purpShape="kite" then "perpendicular" else "not perpendicular";
tans5: if blueShape="equilateral" then 30 else if blueShape="isosceles" then (180-triAngle)/2 else triAngle;

