node3_test: if ((ans1="square" or ans1="rectangle" or ans1="kite") and ans2="perpendicular") or ((ans1="rhombus" or ans1="parallelogram" or ans1="trapezium") and ans2="not perpendicular") then 1 else 0;

/* Node 1: Check first part correct */

