/* Node 3: Check second part consisted with first */
node3_test: if ((ans3="square" or ans3="rectangle" or ans3="kite") and ans4="perpendicular") or ((ans3="rhombus" or ans3="parallelogram" or ans3="trapezium") and ans4="not perpendicular") then 1 else 0;
